package cn.shixu.app;

import android.app.Activity;
import android.content.*;
import android.graphics.Bitmap;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.Bundle;
import android.text.*;
import android.view.*;
import android.widget.*;

/** Image -> editable recognized text -> the existing task editor. No automatic save. */
public class OcrActivity extends Activity {
    public static final String CREATE="cn.shixu.app.OCR_CREATE",TEXT="recognizedText";
    static final int PICK=70;Uri selected;OcrEngine.Job job;boolean loading,destroyed,enhanced;String recognizedText="";ImageView preview;EditText words;TextView status,create;Switch mode;ProgressBar progress;
    int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    TextView label(String value,int size,int color,boolean bold){TextView view=new TextView(this);view.setText(value);view.setTextSize(size);view.setTextColor(color);if(bold)view.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return view;}
    TextView button(String value,boolean primary){TextView view=label(value,14,primary?0xffffffff:0xff4561ee,true);view.setGravity(Gravity.CENTER);GradientDrawable background=new GradientDrawable();background.setColor(primary?0xff4561ee:0xffeef1ff);background.setCornerRadius(dp(14));view.setBackground(background);view.setMinHeight(dp(44));return view;}
    void gap(LinearLayout root,int height){root.addView(new TextView(this),new LinearLayout.LayoutParams(1,dp(height)));}
    @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xfff6f7fb);root.setFocusableInTouchMode(true);root.requestFocus();setContentView(root);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);root.setOnApplyWindowInsetsListener((v,insets)->{if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime());v.setPadding(dp(18),bars.top+dp(8),dp(18),bars.bottom+dp(10));}else v.setPadding(dp(18),insets.getSystemWindowInsetTop()+dp(8),dp(18),insets.getSystemWindowInsetBottom()+dp(10));return insets;});
        LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);heading.addView(label("图片识别",21,0xff20283f,true),new LinearLayout.LayoutParams(0,dp(48),1));TextView close=button("关闭",false);close.setPadding(dp(12),0,dp(12),0);close.setOnClickListener(v->finish());heading.addView(close);root.addView(heading);gap(root,6);
        TextView privacy=label("本机识别 · 图片不上传",15,0xff207561,true);privacy.setPadding(dp(14),dp(11),dp(14),dp(11));GradientDrawable privacyBackground=new GradientDrawable();privacyBackground.setColor(0xffe7f4ee);privacyBackground.setCornerRadius(dp(14));privacy.setBackground(privacyBackground);root.addView(privacy,new LinearLayout.LayoutParams(-1,-2));gap(root,8);
        root.addView(label("请选择清晰的通知截图，必要时先裁剪到正文。",12,0xff828aa0,false));gap(root,10);
        TextView choose=button("选择图片",false);choose.setContentDescription("选择图片进行文字识别");choose.setOnClickListener(v->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/*"),PICK);}catch(ActivityNotFoundException e){status.setText("当前手机没有可用的图片选择器，请启用文件管理或相册后重试。");}});root.addView(choose,new LinearLayout.LayoutParams(-1,dp(44)));gap(root,8);
        enhanced=state!=null&&state.getBoolean("enhanced");recognizedText=state==null?"":state.getString("recognizedText","");mode=new Switch(this);mode.setTextSize(14);mode.setTextColor(0xff4561ee);mode.setTypeface(Typeface.DEFAULT,Typeface.BOLD);mode.setPadding(dp(14),0,dp(14),0);GradientDrawable modeBackground=new GradientDrawable();modeBackground.setColor(0xffeef1ff);modeBackground.setCornerRadius(dp(14));mode.setBackground(modeBackground);mode.setChecked(enhanced);mode.setText(enhanced?"图片增强：已开启":"图片增强：已关闭");mode.setContentDescription("切换照片增强识别");root.addView(mode,new LinearLayout.LayoutParams(-1,dp(44)));gap(root,6);mode.setOnCheckedChangeListener((v,on)->{if(on==enhanced)return;if(loading){mode.setChecked(enhanced);return;}Runnable change=()->{enhanced=on;mode.setChecked(enhanced);mode.setText(enhanced?"图片增强：已开启":"图片增强：已关闭");if(selected!=null)recognize(selected);};if(words.length()>0&&!words.getText().toString().equals(recognizedText)){mode.setChecked(enhanced);new android.app.AlertDialog.Builder(this).setTitle("重新识别这张图片？").setMessage("切换图片增强将替换当前修改过的文字。").setNegativeButton("保留修改",null).setPositiveButton("重新识别",(d,n)->change.run()).show();}else change.run();});
        LinearLayout source=new LinearLayout(this);source.setGravity(Gravity.CENTER_VERTICAL);preview=new ImageView(this);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);preview.setContentDescription("已选图片预览");preview.setVisibility(View.GONE);source.addView(preview,new LinearLayout.LayoutParams(dp(72),dp(72)));LinearLayout info=new LinearLayout(this);info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(8),0,0,0);status=label("选择一张图片开始识别。",13,0xff828aa0,false);info.addView(status);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);progress.setVisibility(View.GONE);info.addView(progress,new LinearLayout.LayoutParams(-1,dp(10)));source.addView(info,new LinearLayout.LayoutParams(0,-2,1));root.addView(source);gap(root,8);
        words=new EditText(this);words.setTextSize(15);words.setTextColor(0xff20283f);words.setHint("识别出的文字会显示在这里，可以直接修改或删除无关内容。");words.setHintTextColor(0xff828aa0);words.setGravity(Gravity.TOP);words.setPadding(dp(14),dp(12),dp(14),dp(12));GradientDrawable background=new GradientDrawable();background.setColor(0xffffffff);background.setCornerRadius(dp(16));background.setStroke(dp(1),0xffe8ebf3);words.setBackground(background);words.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);words.setFilters(new InputFilter[]{new InputFilter.LengthFilter(20000)});words.setContentDescription("识别文字，可修改");root.addView(words,new LinearLayout.LayoutParams(-1,0,1));gap(root,8);
        create=button("核对文字，生成事项",true);create.setContentDescription("用识别文字生成事项");root.addView(create,new LinearLayout.LayoutParams(-1,dp(48)));create.setOnClickListener(v->{String text=words.getText().toString().trim();if(loading||text.isEmpty())return;startActivity(new Intent(this,MainActivity.class).setAction(CREATE).putExtra(TEXT,text).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));finish();});words.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){updateButton();}public void afterTextChanged(Editable s){}});
        if(state!=null){String uri=state.getString("image");if(uri!=null)selected=Uri.parse(uri);words.setText(state.getString("text",""));if(state.getBoolean("loading")&&selected!=null)recognize(selected);else if(words.length()>0)status.setText("识别文字已保留，请核对后生成事项。");}updateButton();
    }
    void updateButton(){boolean enabled=!loading&&words.getText().toString().trim().length()>0;create.setEnabled(enabled);create.setAlpha(enabled?1:.4f);if(mode!=null){mode.setEnabled(!loading);mode.setAlpha(loading?.4f:1);}}
    void recognize(Uri uri){if(job!=null)job.cancel();selected=uri;loading=true;words.setText("");words.setEnabled(false);preview.setVisibility(View.GONE);preview.setImageDrawable(null);status.setText("正在本机识别图片文字…");progress.setVisibility(View.VISIBLE);updateButton();job=OcrEngine.recognize(this,uri,enhanced,new OcrEngine.Listener(){public void preview(Bitmap image){if(destroyed||isFinishing())return;preview.setImageBitmap(image);preview.setVisibility(View.VISIBLE);}public void text(String value){if(destroyed||isFinishing())return;loading=false;words.setEnabled(true);recognizedText=value;words.setText(value);status.setText("识别完成，请核对文字，再生成事项。");progress.setVisibility(View.GONE);updateButton();}public void error(String message){if(destroyed||isFinishing())return;loading=false;words.setEnabled(true);status.setText(message);progress.setVisibility(View.GONE);updateButton();}});}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK&&result==RESULT_OK&&data!=null&&data.getData()!=null)recognize(data.getData());}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(selected!=null)state.putString("image",selected.toString());state.putString("text",words.getText().toString());state.putBoolean("loading",loading);state.putBoolean("enhanced",enhanced);state.putString("recognizedText",recognizedText);}
    @Override protected void onDestroy(){destroyed=true;if(job!=null)job.cancel();preview.setImageDrawable(null);super.onDestroy();}
}
